def render(asset):
    asset_id, title, description, default_color, parts = asset
    lines = [
        "// SPDX-License-Identifier: CC0-1.0",
        "// Original low-poly postal logistics scene prop, millimetres, Z up, base at z = 0.",
        "",
        "meta({",
        f"  name: {json.dumps(asset_id)},",
        "  license: 'CC0-1.0',",
        f"  title: {json.dumps(title)},",
        f"  description: {json.dumps(description + ' Stylized scene geometry. Knobs: overall scale and asset color.')},",
        "  tags: ['postal logistics', 'mail', 'parcel', 'package processing', 'low poly', 'scene prop'],",
        "  kit: 'postal-logistics',",
        "  category: 'prop',",
        "  origin: 'base',",
        "  compat: ['postal', 'postal-processing', 'mailroom', 'logistics', 'scene'],",
        "  triangleBudget: 1800,",
        "});",
        "",
        "const scale = param('scale', 1, { min: 0.7, max: 1.3, step: 0.05, label: 'Overall scale' });",
        f"const color = param('color', {json.dumps(default_color)}, {{ label: 'Asset color' }});",
        "const b = (x:number,y:number,z:number,w:number,d:number,h:number) => box(w,d,h,true).translate(x,y,z+h/2).scale(scale);",
    ]
    if any(part[0] == "cylinder" for part in parts):
        lines.append("const c = (x:number,y:number,z:number,h:number,r:number,s:number) => cylinder(h,r,s).translate(x,y,z).scale(scale);")
    lines.extend(["", f"const p = assembly({json.dumps(asset_id)});"])
    for part in parts:
        if part[0] == "box":
            _, name, x, y, z, w, d, h = part
            shape = f"b({x},{y},{z},{w},{d},{h})"
        else:
            _, name, x, y, z, h, r, segments = part
            shape = f"c({x},{y},{z},{h},{r},{segments})"
        lines.append(f"p.part({json.dumps(name)}, {shape}.color(color));")
    lines.extend(["", "return p.model();", ""])
    return "\n".join(lines)


asset_ids = [asset[0] for asset in ASSETS]
if len(ASSETS) != 52 or len(asset_ids) != len(set(asset_ids)):
    raise SystemExit("postal-logistics wave must contain 52 uniquely named assets")
if any(part[4] < 0 for asset in ASSETS for part in asset[4]):
    raise SystemExit("every postal-logistics component must sit at or above the base plane")

for asset in ASSETS:
    (KIT / f"{asset[0]}.kcad.ts").write_text(render(asset))

(KIT / "kit.json").write_text(
    json.dumps(
        {
            "title": "Postal logistics",
            "description": "Original low-poly parcel induction, scanning, sortation, mail handling, route preparation, and dispatch props with editable scale and color controls.",
        },
        indent=2,
    )
    + "\n"
)
print(f"generated {len(ASSETS)} postal-logistics assets")
